mapper.update:
UPDATE `order`
SET status = #{status}, pay_time = NOW() pay_time, deliver_time = NOW() deliver_time, finish_time = NOW() finish_time, update_time = NOW()
WHERE order_no = #{orderNo}

mapper.select:
